\begin{tikzpicture}[scale=.9]
 \fill[cyan!9] (0,0) circle (1.4);
 \draw[thick] (0,0) circle (1.4);
 \foreach \a in {0,30,...,330}{\draw[cyan!65!black] (0,0)--(\a:1.4);}
 \fill (0,0) circle (.06);
 \node[align=center,text width=4cm,font=\small] at (0,-1.95) {disk\\coherent circle of spokes};
 \begin{scope}[xshift=6cm]
  \fill[cyan!9,even odd rule] (0,0) circle (1.4) (0,0) circle (.48);
  \draw[thick] (0,0) circle (1.4);
  \draw[dashed,thick] (0,0) circle (.48);
  \foreach \a in {0,30,...,330}{\draw[cyan!65!black] (\a:.48)--(\a:1.4);}
  \draw[->,thick] (20:.75) arc (20:315:.75);
  \node[align=center,text width=4cm,font=\small] at (0,-1.95) {punctured disk\\peripheral loop};
 \end{scope}
\end{tikzpicture}
